package com.trampolim.api.hub;
import java.util.*;import java.time.*;
import static com.trampolim.api.hub.HubRules.*;import static com.trampolim.api.radar.RadarModel.*;
import com.trampolim.api.radar.*;import com.trampolim.api.future.FutureModel;
import org.springframework.web.bind.annotation.*;import org.springframework.security.core.annotation.AuthenticationPrincipal;import org.springframework.beans.factory.annotation.Qualifier;import org.springframework.jdbc.core.JdbcTemplate;import org.springframework.http.HttpStatus;
@RestController
public class HubCandidateController {
 private final JdbcTemplate jdbc;private final SkillCatalog skills;private final RadarBridge bridge;private final RadarService radar;
 public HubCandidateController(@Qualifier("jdbcTemplate")JdbcTemplate jdbc,SkillCatalog skills,RadarBridge bridge,RadarService radar){this.jdbc=jdbc;this.skills=skills;this.bridge=bridge;this.radar=radar;}
 @GetMapping("/api/hub/consents")public List<Map<String,Object>> consents(@AuthenticationPrincipal String email){return jdbc.queryForList("SELECT organization_id,institution_name,consent_at FROM hub_candidate_consents WHERE user_id=? ORDER BY organization_id LIMIT 200",skills.user(email));}
 @GetMapping("/api/hub/organizations")public Map<String,Object> organizations(@AuthenticationPrincipal String email,@RequestParam(defaultValue="9223372036854775807")long before,@RequestParam(defaultValue="20")int limit,@RequestParam(defaultValue="")String q){skills.user(email);page(before,limit);text(q,120);return bridge.convert(bridge.get("/public/hub/organizations?before="+before+"&limit="+limit+"&q="+java.net.URLEncoder.encode(q,java.nio.charset.StandardCharsets.UTF_8)),Map.class);}
 @PutMapping("/api/hub/organizations/{id}/consent")@org.springframework.transaction.annotation.Transactional("oportunidadesTransactionManager")@ResponseStatus(HttpStatus.NO_CONTENT)public void consent(@AuthenticationPrincipal String email,@PathVariable long id,@RequestBody Consent input){long user=skills.user(email);if(input==null||!input.consent())bad("Autorize expressamente os indicadores agregados desta instituição.");var organization=bridge.get("/public/hub/organizations/"+id);jdbc.queryForObject("SELECT id FROM app_users WHERE id=? FOR UPDATE",Long.class,user);if(jdbc.queryForObject("SELECT count(*) FROM hub_candidate_consents WHERE user_id=?",Integer.class,user)>=200&&!Boolean.TRUE.equals(jdbc.queryForObject("SELECT EXISTS(SELECT 1 FROM hub_candidate_consents WHERE user_id=? AND organization_id=?)",Boolean.class,user,id)))bad("Limite de autorizações atingido.");jdbc.update("INSERT INTO hub_candidate_consents(user_id,organization_id,institution_name) VALUES (?,?,?) ON CONFLICT(user_id,organization_id) DO UPDATE SET institution_name=EXCLUDED.institution_name,consent_at=CURRENT_TIMESTAMP",user,id,text(organization.path("name").asText(),180));jdbc.update("INSERT INTO future_talent_audit(actor_id,event) VALUES (?,'HUB_AGGREGATE_CONSENT')",user);}
 @DeleteMapping("/api/hub/organizations/{id}/consent")@ResponseStatus(HttpStatus.NO_CONTENT)public void revoke(@AuthenticationPrincipal String email,@PathVariable long id){long user=skills.user(email);jdbc.update("DELETE FROM hub_candidate_consents WHERE user_id=? AND organization_id=?",user,id);jdbc.update("INSERT INTO future_talent_audit(actor_id,event) VALUES (?,'HUB_AGGREGATE_REVOKED')",user);}
 @PostMapping("/api/integrations/hub/candidates")public Map<String,Object> aggregate(@RequestHeader(name="X-Trampolim-Bridge",required=false)String key,@RequestBody CandidateQuery input){bridge.authorize(key);if(input==null||input.organizationId()<1||input.demands()==null||input.demands().size()>200||input.demands().stream().anyMatch(d->d==null||d.id()<1||d.revision()<0)||input.demands().stream().map(DemandScope::id).distinct().count()!=input.demands().size())bad("Escopo inválido.");dates(input.from(),input.to());if(input.demands().isEmpty())return Map.of("status","OK","participants",FutureModel.band(0));var args=new ArrayList<Object>();for(var demand:input.demands()){args.add(demand.id());args.add(demand.revision());}args.add(radar.policy().revision());args.add(input.organizationId());args.add(LocalDate.parse(input.from()));args.add(LocalDate.parse(input.to()).plusDays(1));String query="WITH scope(id,revision) AS (VALUES "+String.join(",",Collections.nCopies(input.demands().size(),"(?::bigint,?::int)"))+") SELECT count(DISTINCT i.user_id) AS participants,count(DISTINCT i.user_id) FILTER(WHERE s.ready=TRUE) AS ready,count(DISTINCT i.user_id) FILTER(WHERE EXISTS(SELECT 1 FROM jsonb_array_elements_text(s.baseline_gaps) x WHERE NOT s.gaps @> to_jsonb(x.value))) AS resolved FROM scope d JOIN future_talent_interests i ON i.demand_id=d.id JOIN hub_candidate_consents h ON h.user_id=i.user_id JOIN app_users u ON u.id=i.user_id AND u.email_verified=TRUE AND u.account_type='PERSON' LEFT JOIN future_preparation_snapshots s ON s.interest_id=i.id AND s.requirements_revision=d.revision AND s.policy_revision=? AND s.checked_at>CURRENT_TIMESTAMP-INTERVAL '48 hours' WHERE h.organization_id=? AND i.created_at>=? AND i.created_at<?";var counts=jdbc.queryForMap(query,args.toArray());long total=((Number)counts.get("participants")).longValue();var result=new LinkedHashMap<String,Object>();result.put("status","OK");result.put("participants",FutureModel.band(total));if(total>=5){result.put("ready",FutureModel.band(((Number)counts.get("ready")).longValue()));result.put("resolvedGapsParticipants",FutureModel.band(((Number)counts.get("resolved")).longValue()));}result.put("notice","Pessoas distintas que autorizaram esta instituição e têm interesse nas previsões do escopo. Faixas e supressão de grupos pequenos; nenhum perfil individual é fornecido.");return result;}
 public List<Map<String,Object>> export(String email){Long user=jdbc.queryForObject("SELECT id FROM app_users WHERE LOWER(email)=LOWER(?)",Long.class,email);return jdbc.queryForList("SELECT organization_id,institution_name,consent_at FROM hub_candidate_consents WHERE user_id=?",user);}
}
